            family_links,
        };
        let rows = sqlx::query!(
            "WITH funding AS (
                SELECT source_declaration_id, amount, NULLIF(btrim(currency, $2), '') AS currency
                FROM exposed.funding_entries WHERE funder_id IN (
                    SELECT member.funder_id FROM exposed.funder_alias_groups member
                    JOIN exposed.funder_alias_groups requested USING (group_id)
                    WHERE requested.funder_id = $1)
             )
