   import hashlib
   import os
   from pathlib import Path

   import psycopg
   from dotenv import load_dotenv

   load_dotenv('.env')
   checksum = hashlib.sha384(
       Path('db/migrations/20260915000000_initial.up.sql').read_bytes()
   ).digest()
