                    left_funder_id: left.id,
                    right_funder_id: right.id,
                    family_key: family.key.clone(),
                    left_name: left.name.clone(),
                    right_name: right.name.clone(),
                });
            }
        }
    }
    let memberships = funders.iter().map(|funder| {
        (funder.id, FunderId::new(components.root(funder.id.value())))
    }).collect();
    Ok(FunderGroups { memberships, alias_links, family_links })
}

struct Components {
    parents: BTreeMap<Uuid, Uuid>,
}

impl Components {
    fn new(funders: &[GroupingFunder]) -> Self {
        Self { parents: funders.iter().map(|funder| (funder.id.value(), funder.id.value())).collect() }
    }

    fn root(&mut self, id: Uuid) -> Uuid {
        let parent = self.parents[&id];
        if parent == id {
            return id;
        }
        let root = self.root(parent);
        self.parents.insert(id, root);
        root
    }

    fn join(&mut self, left: Uuid, right: Uuid) {
        let left = self.root(left);
        let right = self.root(right);
        self.parents.insert(left.max(right), left.min(right));
    }
}
