    sqlx::query!("INSERT INTO exposed.funders (id, funder_name) VALUES ($1, 'Retained old source')", old_id).execute(&pool).await?;
    sqlx::query!("INSERT INTO exposed.funder_aliases (funder_id, funder_alias) VALUES ($1, $2)", old_id, load.funders[0].name).execute(&pool).await?;
